from ansible.galaxy.api import GalaxyAPI, GalaxyError


class MultiGalaxyAPIProxy:
    """A proxy that abstracts talking to multiple Galaxy instances."""

    def __init__(self, apis, concrete_artifacts_manager):
        # type: (Iterable[GalaxyAPI], ConcreteArtifactsManager) -> None
        """Initialize the target APIs list."""
        self._apis = apis
        self._concrete_art_mgr = concrete_artifacts_manager

    def get_collection_versions(self, requirement):
        # type: (Requirement) -> Iterable[Tuple[str, GalaxyAPI]]
        """Get a set of unique versions for FQCN on Galaxy servers."""
        if requirement.is_concrete_artifact:
            return {
                (
                    self._concrete_art_mgr.
                    get_direct_collection_version(requirement),
                    requirement.src,
                ),
            }

        api_lookup_order = (
            (requirement.src, )
            if isinstance(requirement.src, GalaxyAPI)
            else self._apis
        )
        return set(
            (version, api)
            for api in api_lookup_order
            for version in api.get_collection_versions(
                requirement.namespace, requirement.name,
            )
        )

    def get_collection_version_metadata(self, collection_candidate):
        # type: (Candidate) -> CollectionVersionMetadata
        """Retrieve collection metadata of a given candidate."""

        api_lookup_order = (
            (collection_candidate.src, )
            if isinstance(collection_candidate.src, GalaxyAPI)
            else self._apis
        )
        for api in api_lookup_order:
            try:
                version_metadata = api.get_collection_version_metadata(
                    collection_candidate.namespace,
                    collection_candidate.name,
                    collection_candidate.ver,
                )
            except GalaxyError as api_err:
                last_err = api_err
            else:
                self._concrete_art_mgr.save_collection_source(
                    collection_candidate,
                    version_metadata.download_url,
                    version_metadata.artifact_sha256,
                    api.token,
                )
                return version_metadata

        raise last_err

    def get_collection_dependencies(self, collection_candidate):
        # type: (Candidate) -> Dict[str, str]
        # FIXME: return Requirement instances instead?
        """Retrieve collection dependencies of a given candidate."""
        if collection_candidate.is_concrete_artifact:
            return (
                self.
                _concrete_art_mgr.
                get_direct_collection_dependencies
            )(collection_candidate)

        return (
            self.
            get_collection_version_metadata(collection_candidate).
            dependencies
        )

    def get_versions(namespace, name):
        return list(versions.get('%s.%s' % (namespace, name), {}))

    def get_metadata(namespace, name, version):
        dependencies = versions['%s.%s' % (namespace, name)][version]
        return api.CollectionVersionMetadata(namespace, name, version, None, None, dependencies)

    monkeypatch.setattr(galaxy_server, 'get_collection_versions', get_versions)
    monkeypatch.setattr(galaxy_server, 'get_collection_version_metadata', get_metadata)

    test_dir = to_text(tmp_path_factory.mktemp('collection-upgrade'))
    artifacts_manager = collection.concrete_artifact_manager.ConcreteArtifactsManager(
        test_dir, validate_certs=False,
    )
    monkeypatch.setattr(
        artifacts_manager, 'get_direct_collection_dependencies',
        lambda candidate: versions[candidate.fqcn][candidate.ver],
    )
    return versions, galaxy_server, artifacts_manager, test_dir


def install_from_catalog(monkeypatch, catalog, requirements, installed=(), upgrade=False,
                         no_deps=False, allow_pre_release=False):
    versions, galaxy_server, artifacts_manager, output_path = catalog
    installed_collections = [
        Candidate(fqcn, version, output_path, 'dir')
        for fqcn, version in installed
    ]
    monkeypatch.setattr(collection, 'find_existing_collections', lambda path, manager: installed_collections)
    installed_pins = []
    monkeypatch.setattr(collection, 'install', lambda candidate, path, manager: installed_pins.append(candidate))

    collection.install_collections(
        [Requirement(fqcn, constraint, None, 'galaxy') for fqcn, constraint in requirements],
        output_path, [galaxy_server], False, no_deps, False, False,
        allow_pre_release, artifacts_manager, upgrade=upgrade,
    )
    return {candidate.fqcn: candidate.ver for candidate in installed_pins}


def test_upgrade_installs_latest_versions_within_requested_constraints(monkeypatch, collection_catalog):
    versions = collection_catalog[0]
    versions.update({
        'namespace.first': {'1.0.0': {}, '2.0.0': {}, '3.0.0': {}},
        'namespace.second': {'1.0.0': {}, '2.0.0': {}},
    })
    requirements = [('namespace.first', '<3.0.0'), ('namespace.second', '*')]

    installed = install_from_catalog(
        monkeypatch, collection_catalog, requirements,
        installed=[('namespace.first', '1.0.0'), ('namespace.second', '1.0.0')],
        upgrade=True,
    )
    assert installed == {'namespace.first': '2.0.0', 'namespace.second': '2.0.0'}

    installed_again = install_from_catalog(
        monkeypatch, collection_catalog, requirements,
        installed=list(installed.items()), upgrade=True,
    )
    assert installed_again == {}


